sect1.example:
  Gestione degli errori Throwable con un blocco &finally;


<?php
function inverse($x) {
    return 1/$x;
}

try {
    echo inverse(5) . "\n";
} catch (DivisionByZeroError $e) {
    echo 'Caught error: ', $e->getMessage(), "\n";
} finally {
    echo "First finally.\n";
}

try {
    echo inverse(0) . "\n";
} catch (DivisionByZeroError $e) {
    echo 'Caught error: ', $e->getMessage(), "\n";
} finally {
    echo "Second finally.\n";
}

// Continua l'esecuzione
echo "Hello World\n";


  &example.outputs.8;


0.2
First finally.
Caught error: Division by zero
Second finally.
Hello World

  Tutti i blocchi &finally; vengono eseguiti


<?php
try {
    try {
        throw new Exception();
    } finally {
        echo "Inner finally\n";
    }
} catch (Exception $e) {
} finally {
    echo "Outer finally\n";
}


  &example.outputs;


Inner finally
Outer finally

sect2.example:
   Interazione tra &return; in un blocco &finally; e un &return; precedente


<?php
function testReturnTry() {
    try {
        echo 'Within try', "\n";
        return 'try';
    } finally {
        echo 'Within finally', "\n";
        return 'finally';
    }
}

function testReturnCatch() {
    try {
        throw new Exception('foo');
    } catch (Exception $e) {
        echo 'Within catch', "\n";
        return 'catch';
    } finally {
        echo 'Within finally', "\n";
        return 'finally';
    }
}

echo testReturnTry(), "\n";
echo testReturnCatch(), "\n";



   &example.outputs;


Within try
Within finally
finally
Within catch
Within finally
finally

   Interazione tra il blocco &finally; e &return;


<?php
function testReturnTry() {
    try {
        return 'try';
    } finally {
        echo 'finally ';
    }
}

function testReturnCatch() {
    try {
        throw new Exception('foo');
    } catch (Exception $e) {
        return 'catch';
    } finally {
        echo 'finally ';
    }
}

echo testReturnTry(), "\n";
echo testReturnCatch(), "\n";


   &example.outputs;


finally try
finally catch

   Un &return; in un blocco &finally; scarta un'eccezione rilanciata


<?php
function process() {
    try {
        throw new Exception('Original exception');
    } catch (Exception $e) {
        echo 'Caught: ', $e->getMessage(), "\n";
        throw $e;
    } finally {
        echo 'Within finally', "\n";
        return 'finally';
    }
}

try {
    echo process(), "\n";
} catch (Exception $e) {
    echo 'This is never reached', "\n";
}


   &example.outputs;


Caught: Original exception
Within finally
finally

   Eccezione in try e in finally


<?php

try {
    try {
        throw new Exception(message: 'Third', previous: new Exception('Fourth'));
    } finally {
        throw new Exception(message: 'First', previous: new Exception('Second'));
    }
} catch (Exception $e) {
    var_dump(
        $e->getMessage(),
        $e->getPrevious()->getMessage(),
        $e->getPrevious()->getPrevious()->getMessage(),
        $e->getPrevious()->getPrevious()->getPrevious()->getMessage(),
    );
}


   &example.outputs;


string(5) "First"
string(6) "Second"
string(5) "Third"
string(6) "Fourth"


    Blocco &finally; eseguito dopo che un'Exception
    è stata lanciata



<?php
function generate()
{
    try {
        yield 1;
        yield 2;
    } catch (Exception $e) {
        echo 'catch';
    } finally {
        echo "finally\n";
    }
}

try {
    foreach (generate() as $i) {
        echo $i, "\n";
        throw new Exception();
    }
} catch (Exception $e) {
    echo 'outer catch';
}


   &example.outputs.similar;


1
finally
outer catch


    Errore quando si usa &yield; in un blocco &finally; dopo che
    un'Exception è stata lanciata



<?php
function generate()
{
    try {
        yield 1;
        yield 2;
    } catch (Exception $e) {
        echo 'catch';
    } finally {
        echo "finally\n";
        yield 3;
    }
}

try {
    foreach (generate() as $i) {
        echo $i, "\n";
        throw new Exception();
    }
} catch (Exception $e) {
    echo 'outer catch';
}


   &example.outputs.similar;


